export const TOPICS_BY_PART: Record<PartId, Topic[]> = ALL_TOPICS.reduce((acc, topic) => {
  if (!acc[topic.partId]) {
    acc[topic.partId] = [];
  }
  acc[topic.partId].push(topic);
  return acc;
}, {} as Record<PartId, Topic[]>);

export const TOTAL_TOPIC_COUNT = ALL_TOPICS.length;
